using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SoulIntensifierAction", menuName = "Data/Battle/Battle Actions/Sothis/SoulIntensifier Action")]
public class SoulIntensifierAction : MultipleSoulHeatTierAction
{
	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		CastMultipleSoulHeatTierFirstActionSoulHeatVariableAction(delegate
		{
			battleAction.CastTarget(target, source);
		}, delegate
		{
			secondBattleAction.CastTargetAmount(target, secondActionValue, source);
		}, null, amount, source);
	}
}
